from format_lecon import Lesson,paras,table,steps,ABBR,D
from html import escape
import gzip
ABBR.update({'SNC':'système nerveux central','NEC':'entérocolite nécrosante'})
original=gzip.open(D.parents[1]/'ressources_ia/aips/fi_fr/32634.txt.gz','rt').read().splitlines()
def q(start):
    found=[x for x in original if x.startswith(start)]
    assert len(found)==1,(start,len(found))
    return '<blockquote><p>« '+escape(found[0])+' »</p></blockquote>'
l=Lesson('Trouble de la réfraction',1)
doses=l.subwindow('cyclogyl','Cyclogyl : diagnostic sous responsabilité médicale',paras('Le cyclopentolate facilite la mesure en relâchant l’accommodation. Il ne corrige pas durablement une amétropie et n’est pas un traitement à emporter. Les deux concentrations 0,5 % et 1 % de Cyclogyl portent le numéro Swissmedic 32634 ; leurs codes de présentation sont distincts. Le schéma des jeunes enfants ne se confond pas avec celui des enfants plus âgés. Les effets sur le système nerveux central (SNC) font partie des risques à surveiller.')+
    '<h3>Indication et cadre</h3>'+q('Pour obtenir une mydriase')+q('Cyclogyl est utilisé exclusivement')+
    '<h3>Adultes</h3>'+q('Instiller 1 ou 2 gouttes de Cyclogyl 0,5% ou 1,0%')+
    '<h3>Enfants et adolescents</h3>'+q('Instiller 1 ou 2 gouttes de Cyclogyl 0,5% ou 1%')+
    '<h3>Jeunes enfants : uniquement 0,5 %, jamais avant un an</h3>'+q('Instiller 1 goutte de Cyclogyl 0,5%')+q('Cyclogyl ne doit pas être utilisé chez les enfants de moins')+
    '<h3>Contre-indications et angle</h3>'+q('Hypersensibilité connue')+q('Afin de prévenir un glaucome')+
    '<h3>Vulnérabilité et surveillance</h3>'+q('Chez les patients, en particulier les enfants')+q('Les patients particulièrement sensibles')+q('Étant donné le risque')+q('Les enfants doivent rester')+q('Administrer uniquement Cyclogyl')+q('Une sensibilité augmentée')+q('L’efficacité et/ou' if any(x.startswith('L’efficacité et/ou') for x in original) else "L'efficacité et/ou")+
    '<h3>Lentilles et surface oculaire</h3>'+q('Les porteurs de lentilles')+q('Le chlorure de benzalkonium (en fonction')+
    '<h3>Interactions</h3>'+q("L'effet du collyre Cyclogyl")+q("L'utilisation de Cyclogyl en association")+q("En cas d'utilisation de plusieurs")+
    '<h3>Grossesse et allaitement</h3>'+q('Aucune donnée n’est disponible' if any(x.startswith('Aucune donnée n’est disponible') for x in original) else "Aucune donnée n'est disponible")+q('Le risque potentiel')+q("Il n'est pas connu si le principe actif")+
    '<h3>Arrêt et recours urgent</h3>'+paras('Ne pas répéter une instillation en cas de réaction suspecte. Une douleur oculaire importante, une confusion, une hallucination, une convulsion, une hyperthermie ou une atteinte respiratoire impose une évaluation urgente. Les parents ne doivent pas attendre une disparition supposée spontanée de signes graves. La prise en charge toxicologique relève du milieu médical.')+q('Des effets toxiques systémiques (syndrome')+
    '<h3>Délais pharmacologiques</h3>'+q('Cyclogyl bloque la réponse')+paras('La récupération de la pupille, de l’accommodation et de l’aptitude à conduire ne sont pas trois délais interchangeables. La conduite reste suspendue tant que les effets visuels ou généraux gênent la sécurité. La surveillance minimale ne signifie pas absence possible d’un événement plus tardif.'),(22,))
l.add('Un {trouble de la réfraction} empêche l’œil de former une image nette dans certaines conditions de vision. Myopie, hypermétropie et astigmatisme relèvent de la focalisation ; la presbytie correspond à la diminution de l’accommodation avec l’âge. La correction doit être mesurée et la baisse visuelle expliquée.',paras('La réfraction désigne la déviation de la lumière par les milieux optiques de l’œil. Une amétropie est un défaut de mise au point par rapport à la rétine. La presbytie peut s’ajouter à une amétropie préexistante : elle n’est pas le nom de toute difficulté à lire.',
    'Une différence de réfraction entre les yeux est une anisométropie. Elle peut passer inaperçue lorsque la personne utilise surtout le meilleur œil. Chez l’enfant, cette asymétrie peut perturber le développement visuel ; le simple fait de ne pas se plaindre ne permet pas d’écarter une amblyopie.'),(15,16,17,18,20))
l.add('Le {contexte de découverte} dépend de l’âge, des activités et des antécédents. Un défaut de correction peut gêner les apprentissages, la conduite ou le travail de près. Aucun taux suisse commun aux différents troubles réfractifs n’est établi par les sources consultées.',paras('Les symptômes ne suivent pas une présentation identique chez l’enfant et chez l’adulte. Le dépistage pédiatrique peut découvrir une asymétrie avant une plainte explicite. Les antécédents familiaux et les mesures antérieures aident à apprécier une évolution.',
    'La myopie forte comporte des risques oculaires qui dépassent le besoin de verres puissants. Une bonne acuité obtenue avec lunettes ne supprime pas le besoin de surveillance du fond d’œil. À l’âge de la presbytie, une nouvelle difficulté de près peut aussi révéler une hypermétropie jusque-là compensée.'),(15,16,18,20))
l.add('Les {principes optiques} permettent de comprendre la correction. Cornée et cristallin participent à la focalisation ; le cristallin modifie sa puissance lors de l’accommodation. La puissance d’un verre et l’acuité visuelle mesurent des grandeurs différentes.',table(['Situation','Mécanisme simplifié','Correction optique'],[
    ['Myopie','À accommodation relâchée, les rayons d’un objet éloigné convergent en avant de la rétine.','Verre divergent, de puissance négative.'],
    ['Hypermétropie','La puissance de l’œil au repos est insuffisante par rapport à sa longueur ; le foyer serait derrière la rétine.','Verre convergent, de puissance positive, selon la prescription.'],
    ['Astigmatisme','La focalisation diffère selon les méridiens optiques.','Correction cylindrique ou torique avec un axe adapté.'],
    ['Presbytie','L’accommodation disponible diminue avec le vieillissement du cristallin.','Addition adaptée à la distance de travail et à la correction de loin.']
])+paras('L’hypermétrope jeune peut compenser une partie du défaut par accommodation, y compris de loin. Une mesure réalisée sans relâcher cet effort peut sous-estimer l’hypermétropie. À l’inverse, une accommodation excessive peut fausser l’estimation d’une myopie.',
    'La cycloplégie réduit temporairement l’action du muscle ciliaire. Elle améliore la fiabilité de certaines mesures, surtout chez l’enfant, mais ses effets et contre-indications doivent être connus. Une pupille dilatée ne constitue pas, à elle seule, une mesure de réfraction.'),(15,16,17,18,19,22))
l.add('Le risque principal est d’attribuer trop vite une baisse visuelle à un {simple défaut de lunettes}. Le parcours urgent du cours général reste applicable. Une correction qui améliore l’image ne suffit pas à exclure une maladie associée.',paras('🚩 E1 : perte soudaine, nouveau rideau, éclairs récents, douleur avec rougeur ou diplopie aiguë imposent le tri spécialisé décrit dans le cours général. Le myope n’est pas protégé d’un décollement de rétine par le port de lunettes.',
    'Chez un porteur de lentilles, douleur ou rougeur impose leur retrait et un avis ophtalmologique. Une irritation attribuée à une lentille peut cacher une infection cornéenne. Une baisse qui reste insuffisamment expliquée après correction nécessite un examen médical, pas seulement une nouvelle puissance.',
    'Chez l’enfant, un strabisme, une différence de vision ou une mauvaise fixation doivent être évalués sans attendre une plainte scolaire répétée. Le risque d’amblyopie justifie une prise en charge précoce ; cela ne signifie pas que toute anomalie réfractive exige le même traitement.'),(1,4,15,20,21))
l.add('L’interrogatoire précise les {besoins visuels et la correction portée}. La gêne doit être décrite à distance, de près et dans les activités réelles. L’histoire aide à distinguer une correction inadaptée d’un changement oculaire nouveau.',steps('Noter lunettes ou lentilles, ancienneté de la prescription, modalités de port et tolérance. Demander les anciennes mesures si disponibles.','Préciser distance de lecture et activité gênante, caractère constant ou fluctuant, fatigue et évolution. Ne pas conclure à une cause réfractive sur une céphalée isolée.','Chez l’enfant, recueillir observations familiales et scolaires, antécédents de strabisme ou d’amblyopie et coopération aux tests.','Avant cycloplégie, rechercher allergie, réaction anticholinergique antérieure, risque d’angle étroit, fièvre, épilepsie, traitements associés, grossesse ou allaitement.','En projet de chirurgie, préciser attentes, stabilité de la réfraction, maladie oculaire et capacité à respecter le suivi.'),(16,19,20,21,22))
l.add('L’examen associe {acuité, réfraction et santé oculaire}. Il se fait pour chaque œil avec une méthode adaptée à l’âge. Une mesure instrumentale ne dispense pas de rechercher une autre cause de mauvaise vision.',paras('Documenter la vision sans correction et avec la correction habituelle, puis la meilleure acuité obtenue lors de la mesure. Préciser les conditions du test et ses limites de coopération. La comparaison des deux yeux ne remplace pas l’évaluation de chacun.',
    'La réfraction objective et la réponse subjective, lorsque le patient peut participer, sont confrontées. Chez l’enfant ou le jeune sujet dont l’accommodation perturbe la mesure, une cycloplégie peut être nécessaire. La sélection du produit et la vérification des contre-indications précèdent l’instillation.',
    'Examiner alignement, milieux oculaires et fond d’œil selon le contexte. Une acuité restant basse malgré une correction adéquate fait rechercher amblyopie et maladie organique. La présence d’une amétropie ne prouve pas que la rétine, le nerf optique et les autres structures sont normaux.'),(15,16,17,20,22))
l.add('L’{analyse du profil réfractif} combine les deux yeux et les distances utiles. Plusieurs défauts peuvent coexister. Le symptôme dominant oriente la mesure mais ne suffit pas à établir une prescription.',table(['Profil','Hypothèse à mesurer','Point de vigilance'],[
    ['Flou de loin avec meilleure vision rapprochée','Myopie.','Vérifier l’évolution et le fond d’œil selon le risque.'],
    ['Fatigue de près malgré une bonne vision apparente','Hypermétropie compensée ou problème accommodatif.','Ne pas exclure une hypermétropie sur une mesure non cycloplégiée discordante.'],
    ['Flou selon les orientations, de loin et de près','Astigmatisme.','Mesurer puissance et axe ; rechercher une anomalie cornéenne si atypique.'],
    ['Éloignement progressif du texte chez l’adulte','Presbytie possible.','Tenir compte de la correction de loin et de la distance de travail.'],
    ['Différence importante entre les yeux de l’enfant','Anisométropie.','Évaluer le développement visuel et une amblyopie associée.']
]),(15,16,17,18,20))
l.add('Le diagnostic repose sur une {réfraction fiable et concordante}. Il doit expliquer la gêne et le niveau d’acuité obtenu. Une mesure isolée qui varie ou ne concorde pas avec l’examen demande une vérification.',paras('La prescription résulte de l’examen, pas d’un symptôme converti directement en dioptries. L’effort accommodatif, la coopération et les conditions de mesure influencent le résultat. Une discordance entre mesure et retentissement impose de reprendre ces éléments.',
    'Chez l’enfant, il faut distinguer défaut optique et conséquence sur le développement visuel. La correction traite le flou réfractif ; un déficit persistant peut nécessiter un traitement spécifique d’amblyopie. Le suivi confirme les progrès au lieu de supposer que la remise des lunettes clôt le problème.'),(16,20,22))
l.add('Les {examens dirigés} répondent à la question optique et à une éventuelle cause associée. La cycloplégie peut rendre la mesure plus fiable. L’imagerie et les analyses ne sont pas systématiques devant une amétropie simple.',
    '<h3>9.a — Référence</h3>'+paras('La mesure de la réfraction, confrontée à l’acuité et à l’examen oculaire, établit le défaut à corriger. Chez l’enfant et dans les situations où l’accommodation fausse la mesure, une évaluation sous cycloplégie est importante. Les symptômes seuls ne déterminent ni la puissance ni l’axe.')+
    '<h3>9.b — Première intention</h3>'+paras('Mesurer chaque œil, comparer les corrections antérieures et examiner les structures oculaires. Le protocole diagnostique est organisé par l’ophtalmologue. Exemple suisse, avec précautions et doses exactes : ')+doses+
    '<h3>9.c — Alternatives adaptées</h3>'+paras('Adapter les tests à l’âge et à la coopération. Un dépistage signale une anomalie possible ; il ne remplace pas le bilan de prescription. Si le produit cycloplégique est contre-indiqué, le spécialiste choisit une autre stratégie au lieu d’appliquer le même schéma sans contrôle.')+
    '<h3>9.d — Seconde intention</h3>'+paras('Devant astigmatisme atypique, mauvaise acuité corrigée ou projet de chirurgie, compléter le bilan cornéen et oculaire. Les Hôpitaux universitaires de Genève (HUG) conditionnent l’éligibilité au laser à l’examen de la cornée et à la stabilité réfractive. Les examens complémentaires visent une question précise, sans batterie automatique.'),(19,20,22))
l.add('L’{arbre de décision} distingue urgence, mesure et correction. La sécurité et le développement visuel priment sur le confort immédiat. Une évolution défavorable entraîne une nouvelle évaluation.',steps('Si signe d’alarme, alors appliquer le parcours urgent avant toute nouvelle prescription optique.','Si enfant ou mesure discordante, alors évaluer l’accommodation et l’indication d’une cycloplégie supervisée.','Si défaut réfractif confirmé et examen concordant, alors choisir correction adaptée aux deux yeux et aux activités.','Si acuité insuffisante malgré correction, alors rechercher amblyopie ou cause organique au lieu d’augmenter arbitrairement la puissance.','Si lentilles envisagées, alors réaliser adaptation, apprentissage d’hygiène et suivi ; douleur ou rougeur conduit à leur retrait et à un avis.','Si chirurgie demandée, alors évaluer éligibilité, attentes et risques ; les lunettes et lentilles restent des alternatives.'),(4,19,20,21,22))
l.add('La {prise en charge} repose d’abord sur une correction optique adaptée. Les lentilles demandent apprentissage et surveillance ; la chirurgie nécessite une sélection individuelle. Le collyre de cycloplégie sert à l’examen et ne remplace pas la correction.',
    '<h3>11.A — But</h3>'+paras('Obtenir une vision utile et confortable, préserver le développement visuel chez l’enfant et identifier les maladies associées. La prescription est adaptée aux activités et au résultat réellement obtenu.')+
    '<h3>11.B — Moyens</h3>'+paras('Les lunettes constituent une correction réglable et réversible. Le choix de verres tient compte du défaut, des deux yeux et de la distance de travail. Chez l’enfant, expliquer les modalités prescrites à la famille et vérifier que la monture permet un port effectif.',
    'Les lentilles nécessitent une adaptation et un calendrier de port individualisés. Respecter renouvellement, entretien et hygiène. Retirer les lentilles pour les activités aquatiques, et immédiatement en cas de rougeur, douleur ou sensation de corps étranger, puis consulter. Ne pas réutiliser une lentille journalière.',
    'La chirurgie réfractive se discute après bilan et information sur les alternatives. Les critères publiés par les HUG pour leur parcours laser comprennent un âge d’au moins 21 ans révolus, une réfraction stable sur les deux dernières années et une cornée compatible. Ce sont des critères de ce parcours, pas une règle légale universelle. Grossesse et allaitement conduisent à différer cette chirurgie.',
    'Corriger la vision de loin ne restaure pas l’accommodation perdue avec l’âge. La monovision fait un compromis entre les yeux et n’est pas toujours tolérée ; une simulation préalable peut aider à apprécier ce compromis. Aucune promesse de suppression définitive de toutes les lunettes n’est faite.',
    'Chez l’enfant, une amblyopie associée et une myopie évolutive demandent un suivi spécifique. Les modalités de contrôle de progression sont choisies par le spécialiste selon le bilan. Une simple correction optique et une stratégie visant à freiner l’évolution ne sont pas la même intervention.')+
    '<h3>11.C — Surveillance</h3>'+paras('Contrôler acuité, tolérance, port réel et évolution de la réfraction. Réévaluer les difficultés persistantes. Après cycloplégie, appliquer les précautions du produit et reconnaître les effets généraux ; ne pas assimiler automatiquement malaise ou agitation à une gêne visuelle normale.')+
    '<h3>11.D — Pronostic et suivi</h3>'+paras('L’amélioration optique dépend aussi de la santé de l’œil et du développement visuel antérieur. Les risques rétiniens d’une myopie forte restent à surveiller même lorsque la correction est satisfaisante. La fréquence des contrôles est individualisée selon âge, progression, symptômes et maladie associée.'),(15,18,19,20,21,22))
l.add('La {prévention} associe habitudes visuelles, dépistage et sécurité du port. Les mesures générales ne corrigent pas une amétropie déjà mesurée. Elles complètent les lunettes ou lentilles et le suivi, sans les remplacer.',paras('Favoriser les activités extérieures et éviter un travail de près prolongé à très courte distance participe aux conseils donnés aux jeunes myopes. Ces mesures ne garantissent pas l’arrêt d’une progression et ne remplacent pas l’examen.',
    'Pour les lentilles, le lavage des mains et le respect du produit d’entretien font partie du soin. Une bonne vision avec la lentille n’autorise pas à dépasser les modalités de port. Les signes de douleur et de rougeur doivent être connus avant la première utilisation.',
    'Chez l’enfant, le dépistage et le port de la correction prescrite réduisent le risque de laisser persister un déficit réfractif amblyogène. Les difficultés de coopération ou d’accès aux lunettes sont discutées avec l’équipe pour organiser une solution réelle.'),(15,20,21))
l.add('Les {repères pratiques} sont la mesure fiable, l’examen oculaire et le suivi. Une correction n’est pas un certificat de santé de l’œil. Les risques du diagnostic pharmacologique sont expliqués avant son utilisation.',steps('Mesurer les deux yeux et les besoins à différentes distances.','Distinguer amétropie, presbytie et amblyopie associée.','Relâcher l’accommodation lorsque la mesure l’exige, dans un cadre médical adapté.','Ne pas utiliser Cyclogyl avant un an ni en angle étroit ; appliquer les autres restrictions de sa notice.','Rechercher une autre cause si la vision corrigée reste insuffisante.','Conserver le suivi du myope à risque et les consignes urgentes.','Organiser hygiène et contrôle des lentilles, ainsi qu’une information réaliste avant chirurgie.'),(15,16,18,19,20,21,22))
l.quiz([
    ('Question 1 — Dioptries et acuité visuelle sont-elles la même mesure ?', 'Non. Les dioptries expriment une puissance optique ; l’acuité évalue la résolution visuelle. Une puissance de verre ne permet pas de déduire à elle seule l’état de la rétine.'),
    ('Question 2 — Une bonne vision de loin exclut-elle une hypermétropie chez l’enfant ?', 'Non. L’accommodation peut compenser le défaut et le masquer à une mesure insuffisamment contrôlée.'),
    ('Question 3 — Quel signe optique corrige habituellement la myopie ?', 'Une puissance négative, divergente. La prescription reste fondée sur la mesure et la tolérance, pas sur le seul récit du flou.'),
    ('Question 4 — La presbytie disparaît-elle après correction laser de la vision de loin ?', 'Non. Une modification de la cornée ne restaure pas l’accommodation perdue du cristallin. Une correction de près peut rester nécessaire.'),
    ('Question 5 — L’astigmatisme concerne-t-il seulement la vision de loin ?', 'Non. Il peut altérer la netteté à plusieurs distances ; son axe et sa puissance doivent être mesurés.'),
    ('Question 6 — Un enfant sans plainte ne nécessite-t-il jamais de bilan ?', 'Non. Une asymétrie ou une amblyopie peut être peu perçue. Les observations et le dépistage guident l’évaluation.'),
    ('Question 7 — Le port de lunettes supprime-t-il le risque rétinien de la myopie forte ?', 'Non. La correction de l’image ne supprime pas les risques liés à la structure de l’œil ; le suivi reste indiqué.'),
    ('Question 8 — Peut-on remettre Cyclogyl au patient pour réaliser la cycloplégie à domicile ?', 'Non. La notice suisse le réserve exclusivement au médecin à des fins diagnostiques et précise qu’il n’est pas destiné à être remis aux patients.'),
    ('Question 9 — Le schéma jeunes enfants permet-il son usage chez un nourrisson de moins d’un an ?', 'Non. La restriction explicite avant un an prime. Chez les jeunes enfants éligibles, seule la concentration 0,5 % est prévue et la surveillance est indispensable.'),
    ('Question 10 — Une dilatation est-elle sans risque chez une personne avec angle étroit ?', 'Non. L’angle étroit anatomique ou le glaucome à angle étroit figure dans les contre-indications de Cyclogyl. L’évaluation précède l’instillation.'),
    ('Question 11 — Une agitation importante après le collyre peut-elle être ignorée ?', 'Non. Un effet anticholinergique systémique est possible. Arrêter les nouvelles instillations et organiser l’évaluation adaptée, urgente si signes graves.'),
    ('Question 12 — Une lentille douloureuse doit-elle simplement être remise après rinçage ?', 'Non. Retirer la lentille et demander un avis ophtalmologique. Une infection cornéenne peut menacer la vision.'),
    ('Question 13 — Une mauvaise acuité corrigée justifie-t-elle toujours un verre plus fort ?', 'Non. Il faut vérifier la mesure et rechercher amblyopie ou maladie organique. La puissance ne remplace pas le diagnostic.'),
    ('Question 14 — Les critères HUG de chirurgie sont-ils une garantie de résultat ?', 'Non. Ils organisent la sélection ; un bilan individuel et une information sur les risques et limites restent nécessaires.')
],(15,16,17,18,19,20,21,22))
l.write()
